resource "aws_sagemaker_pipeline" "example" {
  pipeline_name         = "example"
  pipeline_display_name = "example"
  role_arn              = aws_iam_role.example.arn

  pipeline_definition = jsonencode({
    Version = "2020-12-01"
    Steps = [{
      Name = "Test"
      Type = "Fail"
      Arguments = {
        ErrorMessage = "test"
      }
    }]
  })
}

resource "aws_iam_role" "example" {
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

data "aws_sagemaker_prebuilt_ecr_image" "test" {
  repository_name = "kmeans"
}

responsePreview:
The following Terraform configuration creates an AWS SageMaker Pipeline resource with a minimal valid pipeline definition. It also creates the required IAM execution role for SageMaker and attaches the AWS-managed `AmazonSageMakerFullAccess` policy so the pipeline has permissions to run SageMaker workflows.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the SageMaker Pipeline will be created."
  type        = string
  default     = "us-east-1"
}

variable "pipeline_name_prefix" {
  description = "Prefix for the SageMaker Pipeline name."
  type        = string
  default     = "example-sagemaker-pipeline"
}

resource "random_id" "suffix" {
  byte_length = 4
}

data "aws_iam_policy_document" "sagemaker_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

